DROP TABLE IF EXISTS `points`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `points` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `code` varchar(255) DEFAULT NULL,
  `name` varchar(255) DEFAULT NULL,
  `type` int(11) DEFAULT NULL,
  `status` int(11) DEFAULT NULL,
  `classificationId_id` int(11) DEFAULT NULL,
  `controller_id` int(11) DEFAULT NULL,
  `address_id` int(11) DEFAULT NULL,
  `categoryId_id` int(11) DEFAULT NULL,
  `opening_time` time DEFAULT NULL,
  `closing_time` time DEFAULT NULL,
  `webpage` varchar(255) DEFAULT NULL,
  `comments` varchar(255) DEFAULT NULL,
  `deleted` tinyint(1) DEFAULT NULL,
  `extNumber` int(11) DEFAULT NULL,
  `intNumber` varchar(5) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `urlGoogleMaps` varchar(650) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `neighborhood` varchar(255) DEFAULT NULL,
  `zipcode` int(11) DEFAULT NULL,
  `city_id` int(11) DEFAULT NULL,
  `state_id` int(11) DEFAULT NULL,
  `country_id` int(11) DEFAULT NULL,
  `activitytime` time DEFAULT '00:02:00',
  `phone` varchar(45) DEFAULT NULL,
  `contact` varchar(45) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `code_unique` (`name`,`code`),
  KEY `IDX_27BA8E29F5B7AF75` (`address_id`),
  KEY `IDX_27BA8E29F6D1A74B` (`controller_id`),
  KEY `IDX_27BA8E29683BBB0F` (`categoryId_id`),
  KEY `IDX_27BA8E296715CEF6` (`classificationId_id`),
  CONSTRAINT `FK_27BA8E296715CEF6` FOREIGN KEY (`classificationId_id`) REFERENCES `classification` (`id`),
  CONSTRAINT `FK_27BA8E29683BBB0F` FOREIGN KEY (`categoryId_id`) REFERENCES `categories` (`id`),
  CONSTRAINT `FK_27BA8E29F5B7AF75` FOREIGN KEY (`address_id`) REFERENCES `address` (`id`),
  CONSTRAINT `FK_27BA8E29F6D1A74B` FOREIGN KEY (`controller_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5227 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;
