DROP TABLE IF EXISTS `product`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `product` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `client_id` int(11) DEFAULT NULL,
  `catalog_id` int(11) DEFAULT NULL,
  `name` varchar(80) NOT NULL,
  `last_name` varchar(100) DEFAULT NULL,
  `cell` varchar(20) DEFAULT NULL,
  `description` varchar(600) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
  `price` decimal(10,2) NOT NULL,
  `price_list` decimal(10,2) NOT NULL,
  `stock` int(11) NOT NULL,
  `provition_time` longtext NOT NULL,
  `maker` longtext NOT NULL,
  `sku` varchar(50) NOT NULL,
  `warranty` int(11) NOT NULL,
  `weight` decimal(7,2) NOT NULL,
  `width` decimal(5,2) NOT NULL,
  `height` decimal(5,2) NOT NULL,
  `depth` decimal(5,2) NOT NULL,
  `color` varchar(30) NOT NULL,
  `size` decimal(11,2) DEFAULT NULL,
  `offer` int(11) NOT NULL,
  `status` int(11) NOT NULL,
  `variants_use` int(11) NOT NULL,
  `visible` int(11) NOT NULL,
  `new_start_date` datetime NOT NULL,
  `new_end_date` datetime NOT NULL,
  `product_order` int(11) NOT NULL,
  `featured` int(11) NOT NULL,
  `price_creditos` decimal(10,2) NOT NULL,
  `id_payroll` varchar(50) DEFAULT NULL,
  `priority` varchar(5) DEFAULT NULL,
  `disability` varchar(255) DEFAULT NULL,
  `gender` char(2) DEFAULT NULL,
  `biometric` tinyint(1) DEFAULT NULL,
  `notification_method` char(1) DEFAULT NULL,
  `notify_contact` varchar(100) DEFAULT NULL,
  `clasificacion1` varchar(100) DEFAULT NULL,
  `clasificacion2` varchar(100) DEFAULT NULL,
  `clasificacion3` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `IDX_D34A04AD19EB6921` (`client_id`),
  KEY `IDX_D34A04ADCC3C66FC` (`catalog_id`),
  CONSTRAINT `FK_D34A04AD19EB6921` FOREIGN KEY (`client_id`) REFERENCES `users` (`id`),
  CONSTRAINT `FK_D34A04ADCC3C66FC` FOREIGN KEY (`catalog_id`) REFERENCES `catalog` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=937 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

