DROP TABLE IF EXISTS `tblbalancegeneral`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tblbalancegeneral` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `dtdFecha` date DEFAULT NULL,
  `strReferencia` varchar(255) DEFAULT NULL,
  `strConcepto` varchar(255) DEFAULT NULL,
  `strEstatus` varchar(255) DEFAULT NULL,
  `fltMonto` double DEFAULT NULL,
  `fltCreditos` double DEFAULT NULL,
  `fltIngreso` double DEFAULT NULL,
  `fltEgreso` double DEFAULT NULL,
  `fltBalance` double DEFAULT NULL,
  `dtdTimeStamp` datetime NOT NULL,
  `intIdCliente` int(11) DEFAULT NULL,
  `intIdPagos` int(11) DEFAULT NULL,
  `intIdTransferenciaCreditos` int(11) DEFAULT NULL,
  `intIdTipoConcepto` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `IDX_6FAF3C1B3736EF0` (`intIdCliente`),
  KEY `IDX_6FAF3C1ED4D2A90` (`intIdPagos`),
  KEY `IDX_6FAF3C1329F0CD3` (`intIdTransferenciaCreditos`),
  KEY `IDX_6FAF3C1F65A6938` (`intIdTipoConcepto`),
  CONSTRAINT `FK_6FAF3C1329F0CD3` FOREIGN KEY (`intIdTransferenciaCreditos`) REFERENCES `tbltransferenciacreditos` (`id`),
  CONSTRAINT `FK_6FAF3C1B3736EF0` FOREIGN KEY (`intIdCliente`) REFERENCES `users` (`id`),
  CONSTRAINT `FK_6FAF3C1ED4D2A90` FOREIGN KEY (`intIdPagos`) REFERENCES `tblpagos` (`id`),
  CONSTRAINT `FK_6FAF3C1F65A6938` FOREIGN KEY (`intIdTipoConcepto`) REFERENCES `tbltipoconcepto` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2816 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

