CREATE DEFINER=`adminhub`@`localhost` PROCEDURE `sp_get_zone_by_user`(IN
	p_id int
	)
BEGIN	
if p_id  = 0 then
select id, name from zone where id in (select zone_id from user_zone) order by name;
else 
