BEGIN
		declare TABLE_NOT_FOUND inT default 0;
		declare continue handler for 1051 SET TABLE_NOT_FOUND = 1;
		 begin
			drop table test;
		 end;
		IF TABLE_NOT_FOUND = 1 then
			SELECT 'Tabla no existe' result;
		END if;
    END ;;
